import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    K = int(input_data[1])

    if N < K:
        print(min(N, K - N))
    else:
        N = N % K
        print(min(N, K - N))

if __name__ == "__main__":
    solve()
